# ---------- helpers ----------
def db():
    if "db" not in g:
        g.db = sqlite3.connect(DB); g.db.row_factory = sqlite3.Row; g.db.execute("pragma foreign_keys=on")
    return g.db
@app.teardown_appcontext
def _close(e):
    d = g.pop("db", None)
    if d: d.close()
def q(s, a=()): return db().execute(s, a).fetchall()
def one(s, a=()):
    r = q(s, a); return r[0] if r else None
def ex(s, a=()):
    c = db().execute(s, a); db().commit(); return c.lastrowid
def now(): return dt.datetime.now(dt.timezone(dt.timedelta(hours=5, minutes=30))).strftime("%Y-%m-%d %H:%M:%S")
def today(): return now()[:10]
def dmy(d): return f"{d[8:10]}-{d[5:7]}-{d[:4]}" if d else ""
def st(k):
    r = one("select v from settings where k=?", (k,)); return r["v"] if r else DEF[k]
def log(a): ex("insert into audit(user_id,action,at) values(?,?,?)", (session.get("uid"), a, now()))
def notify(uid, m): ex("insert into notifications(user_id,msg,at) values(?,?,?)", (uid, m, now()))
def me():
    if "u" not in g: g.u = one("select * from users where id=? and active=1", (session.get("uid"),)) if session.get("uid") else None
    return g.u
def need(*roles):
    def d(f):
        @wraps(f)
        def w(*a, **k):
            if not me(): return redirect("/login")
            if roles and me()["role"] not in roles: abort(403)
            return f(*a, **k)
        return w
    return d
def inl(ids): return ",".join("?" * len(ids))
def scope():
    u = me()
    if u["role"] in ("admin", "partner"): return [r["id"] for r in q("select id from users where active=1")]
    if u["role"] == "manager": return [u["id"]] + [r["id"] for r in q("select id from users where manager_id=? and active=1", (u["id"],))]
    return [u["id"]]
def vis():
    u = me()
    if u["role"] in ("admin", "partner"): return "1=1", ()
    ids = scope()
    return f"(a.manager_id=? or a.id in (select assignment_id from amembers where user_id in ({inl(ids)})))", (u["id"], *ids)
def wdays(s, e):
    offs = {int(x) for x in st("weekly_offs").split(",") if x.strip()}
    hol = {r["date"] for r in q("select date from holidays where active=1")}
    d, end, out = dt.date.fromisoformat(s), dt.date.fromisoformat(min(e, today())), []
    while d <= end:
        if d.weekday() not in offs and d.isoformat() not in hol: out.append(d.isoformat())
        d += dt.timedelta(1)
    return out
def rng():
    t = dt.date.fromisoformat(today()); r = request.args.get("r", "month")
    try:
        if r == "today": s = e = t
        elif r == "week": s = t - dt.timedelta(t.weekday()); e = s + dt.timedelta(6)
        elif r == "fy": y = t.year if t.month >= 4 else t.year - 1; s, e = dt.date(y, 4, 1), dt.date(y + 1, 3, 31)
        elif r == "custom": s, e = dt.date.fromisoformat(request.args["from"]), dt.date.fromisoformat(request.args["to"])
        else: r = "month"; s, e = t.replace(day=1), t
    except Exception:
        r = "month"; s, e = t.replace(day=1), t
    return s.isoformat(), e.isoformat(), r

# ---------- html helpers ----------
def H(s): return Markup(s)
def tbl(heads, rows):
    if not rows: return H('<p class="empty">No records found.</p>')
    c = lambda x: esc("" if x is None else x)
    return H('<div class="tw"><table><tr>' + "".join(f"<th>{esc(h)}</th>" for h in heads) + "</tr>" + "".join("<tr>" + "".join(f"<td>{c(x)}</td>" for x in r) + "</tr>" for r in rows) + "</table></div>")
def inp(n, l, t="text", v="", req=False, x=""): return f'<label>{esc(l)}<input name="{n}" type="{t}" value="{esc(v if v is not None else "")}" {"required" if req else ""} {x}></label>'
def sel(n, l, opts, cur=None, multi=False, blank=False):
    cur = [str(c) for c in (cur if isinstance(cur, (list, tuple)) else [cur])]
    o = ('<option value=""></option>' if blank else "") + "".join(f'<option value="{esc(v)}" {"selected" if str(v) in cur else ""}>{esc(t)}</option>' for v, t in opts)
    return f'<label>{esc(l)}<select name="{n}" {"multiple size=5" if multi else ""}>{o}</select></label>'
def F(action, inner, btn="Save", cls="grid"):
    return H(f'<form method="post" action="{action}" class="{cls}"><input type="hidden" name="_t" value="{session["t"]}">{inner}<button class="btn">{esc(btn)}</button></form>')
def people(roles=None): return [(r["id"], r["name"]) for r in q("select id,name from users where active=1 order by name") if True]
def filt(r):
    o = "".join(f'<option value="{k}" {"selected" if k == r else ""}>{v}</option>' for k, v in [("today", "Today"), ("week", "This Week"), ("month", "This Month"), ("fy", "Financial Year"), ("custom", "Custom Range")])
    return H(f'<form class="bar"><select name="r">{o}</select><input type="date" name="from" value="{esc(request.args.get("from", ""))}"><input type="date" name="to" value="{esc(request.args.get("to", ""))}"><button class="btn">Apply</button></form>')

