def page(title, *body):
    u = me()
    nav = "".join(f'<a href="{h}" class="{"on" if request.path == h else ""}">{esc(n)}</a>' for n, h, r in NAV if not r or u["role"] in r)
    fl = "".join(f'<div class="flash {c}">{esc(m)}</div>' for c, m in get_flashed_messages(with_categories=True))
    side = f'<div class="side"><div class="lg0"><img src="{LOGO}" alt="AJ TaskSphere"></div><h2>{esc(st("firm_name"))}</h2><small>{esc(u["name"])} ({u["role"]})</small><br><br>{nav}<form method="post" action="/logout"><input type="hidden" name="_t" value="{session["t"]}"><button class="btn r" style="margin-top:14px">Logout</button></form></div>'
    return f'<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | AJ TaskSphere</title><link rel="icon" href="{LOGO}"><style>{CSS}</style></head><body>{side}<div class="main">{fl}<h2>{esc(title)}</h2>{"".join(str(b) for b in body)}</div></body></html>'

@app.before_request
def _pre():
    session.permanent = True
    if "t" not in session: session["t"] = secrets.token_hex(16)
    if request.method == "POST" and request.form.get("_t") != session["t"]: abort(400)
def csvout(name, heads, rows):
    s = io.StringIO(); w = csv.writer(s); w.writerow(heads); w.writerows(rows)
    return Response(s.getvalue(), mimetype="text/csv", headers={"Content-Disposition": f"attachment; filename={name}.csv"})

