# ---------- auth ----------
@app.route("/login", methods=["GET", "POST"])
def login():
    if request.method == "POST":
        k = request.form["email"].strip().lower()
        m = q("select * from users where active=1 and (lower(email)=? or lower(emp_id)=? or lower(name)=?)", (k, k, k)); u = m[0] if len(m) == 1 else None
        if u and cph(u["pw"], request.form["password"]):
            session.clear(); session["uid"] = u["id"]; session["t"] = secrets.token_hex(16)
            ex("insert into audit(user_id,action,at) values(?,?,?)", (u["id"], "Login", now())); return redirect("/")
        ex("insert into audit(user_id,action,at) values(?,?,?)", (None, "Failed login: " + request.form["email"][:80], now()))
        flash("Invalid credentials or inactive account", "err")
    fl = "".join(f'<div class="flash {c}">{esc(m)}</div>' for c, m in get_flashed_messages(with_categories=True))
    return f'<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AJ TaskSphere | Login</title><link rel="icon" href="{LOGO}"><style>{CSS}body{{display:grid;place-items:center;min-height:100vh;background:linear-gradient(135deg,#1e3a8a,#4f46e5,#7c3aed)}}.lg{{background:#fff;padding:30px;border-radius:18px;width:400px;max-width:92vw}}</style></head><body><form method="post" class="lg"><img src="{LOGO}" style="width:100%" alt="AJ TaskSphere"><p style="color:#64748b;text-align:center;font-size:13px">Sign in to continue</p>{fl}<input type="hidden" name="_t" value="{session["t"]}"><label>Login ID (email, employee ID or full name)<input name="email" type="text" required></label><br><label>Password<input name="password" type="password" required></label><br><button class="btn" style="width:100%">Sign in</button></form></body></html>'
@app.route("/logout", methods=["POST"])
def logout():
    if session.get("uid"): log("Logout")
    session.clear(); return redirect("/login")

# ---------- dashboard ----------
def remind():
    if now()[11:16] < st("cutoff") or today() not in wdays(today(), today()): return
    m = f"EOD pending for {dmy(today())}. Please submit before the cut-off."
    for r in q(f"select id from users where active=1 and id not in (select user_id from eods where work_date=? and status in {OK})", (today(),)):
        if not one("select 1 from notifications where user_id=? and msg=?", (r["id"], m)): notify(r["id"], m)
    lim = (dt.date.fromisoformat(today()) + dt.timedelta(2)).isoformat()
    for a in q("select a.id,a.code,a.due,m.user_id from assignments a join amembers m on m.assignment_id=a.id where a.status not in('Completed','Cancelled') and a.due<=?", (lim,)):
        m = f"Assignment {a['code']} is {'OVERDUE since' if a['due'] < today() else 'due on'} {dmy(a['due'])}."
        if not one("select 1 from notifications where user_id=? and msg=? and at like ?", (a["user_id"], m, today() + "%")): notify(a["user_id"], m)

@app.route("/")
@need()
def dash():
    remind(); u = me(); s, e, r = rng(); ids = scope(); I = inl(ids); A = (*ids, s, e)
    days = wdays(s, e); ds = set(days)
    base = f"from eod_entries n join eods d on d.id=n.eod_id where d.user_id in ({I}) and d.work_date between ? and ? and d.status in {OK}"
    tot = one(f"select coalesce(sum(n.mins),0)/60.0 h {base}", A)["h"]
    sub = sum(1 for x in q(f"select work_date from eods where user_id in ({I}) and work_date between ? and ? and status in {OK}", A) if x["work_date"] in ds)
    comp = f"{100 * sub / (len(days) * len(ids)):.1f}%" if days else "n/a"
    util = f"{100 * tot / (len(days) * float(st('daily_hours')) * len(ids)):.1f}%" if days else "n/a"
    w, wa = vis(); t = today()
    cnt = lambda c: one(f"select count(*) c from assignments a where {w} and {c}", wa)["c"]
    op = "a.status not in('Completed','Cancelled')"
    soon = (dt.date.fromisoformat(t) + dt.timedelta(7)).isoformat()
    pt = 0
    if t in wdays(t, t): pt = len(ids) - one(f"select count(*) c from eods where user_id in ({I}) and work_date=? and status in {OK}", (*ids, t))["c"]
    pend = one(f"select count(*) c from eods where user_id in ({I}) and status in ('Submitted','Under Review') and user_id<>?", (*ids, u["id"]))["c"]
    K = [("Total Hours", f"{tot:.1f}", "#2563eb"), ("Utilization", util, "#7c3aed"), ("EOD Compliance", comp, "#059669"), ("Open Assignments", cnt(op), "#4f46e5"), ("Pending EODs Today", pt, "#d97706"), ("Overdue Assignments", cnt(op + f" and a.due<'{t}'"), "#f43f5e"), ("Due in 7 Days", cnt(op + f" and a.due between '{t}' and '{soon}'"), "#0d9488"), ("Pending Approvals", pend, "#1d4ed8")]
    kp = "".join(f'<div class="kp" style="--c:{c}"><b>{v}</b><span>{l}</span></div>' for l, v, c in K)
    pl = lambda sql, a: {"l": [x[0] for x in q(sql, a)], "v": [round(x[1] or 0, 2) for x in q(sql, a)]}
    D = {"emp": pl(f"select u.name,sum(n.mins)/60.0 {base.replace('from eod_entries n','from eod_entries n join users u on u.id=(select user_id from eods where id=n.eod_id)')} group by u.id", A),
         "cli": pl(f"select c.name,sum(n.mins)/60.0 {base} group by 1".replace(f"{base} group by 1", f"from eod_entries n join eods d on d.id=n.eod_id join assignments a on a.id=n.assignment_id join clients c on c.id=a.client_id where d.user_id in ({I}) and d.work_date between ? and ? and d.status in {OK} group by c.id"), A),
         "day": pl(f"select d.work_date,sum(n.mins)/60.0 {base} group by d.work_date order by 1", A),
         "ast": pl(f"select a.status,count(*) from assignments a where {w} group by a.status", wa)}
    js = json.dumps(D).replace("<", "\\u003c")
    ch = H(f'''<div class="cards"><div class="card"><h3>Hours by Team Member</h3><canvas id="c1"></canvas></div><div class="card"><h3>Client-wise Hours</h3><canvas id="c2"></canvas></div><div class="card"><h3>Daily Hours Trend</h3><canvas id="c3"></canvas></div><div class="card"><h3>Assignment Status</h3><canvas id="c4"></canvas></div></div>
<script type="application/json" id="d">{js}</script><script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js"></script><script>
const D=JSON.parse(document.getElementById('d').textContent),C=['#2563eb','#059669','#d97706','#7c3aed','#f43f5e','#0d9488','#4f46e5','#eab308'];
function mk(id,t,o){{const el=document.getElementById(id);if(!o.l.length){{el.replaceWith(Object.assign(document.createElement('p'),{{className:'empty',textContent:'No data for this period'}}));return}}
new Chart(el,{{type:t,data:{{labels:o.l,datasets:[{{data:o.v,backgroundColor:t=='line'?'#4f46e5':C,borderColor:'#4f46e5'}}]}},options:{{plugins:{{legend:{{display:t=='doughnut'}}}}}}}})}}
mk('c1','bar',D.emp);mk('c2','doughnut',D.cli);mk('c3','line',D.day);mk('c4','doughnut',D.ast);</script>''')
    ban = H(f'<div class="ban"><h1>Welcome, {esc(u["name"])}</h1>{esc(st("firm_name"))} | AJ TaskSphere<br>{dt.date.fromisoformat(t).strftime("%A")}, {dmy(t)} | Period: {dmy(s)} to {dmy(e)} | {len(days)} working days</div>')
    return page("Dashboard", ban, filt(r), H(f'<div class="k">{kp}</div>'), ch)

# ---------- EOD ----------
def erow(opts, x=None):
    g_ = lambda k, d="": x[k] if x is not None and x[k] is not None else d
    m = g_("mins", 0)
    ws = "".join(f'<option {"selected" if g_("wstatus") == o else ""}>{o}</option>' for o in ["In Progress", "Completed", "Blocked", "Awaiting Review"])
    ao = "".join(f'<option value="{v}" {"selected" if str(v) == str(g_("assignment_id")) else ""}>{esc(t)}</option>' for v, t in opts)
