@app.route("/team")
@need(*MG)
def team():
    a = request.args; ids = scope(); I = inl(ids); t = dt.date.fromisoformat(today())
    f, to = a.get("from") or (t - dt.timedelta(7)).isoformat(), a.get("to") or t.isoformat()
    sql = f"select e.*,u.name,coalesce((select sum(mins) from eod_entries where eod_id=e.id),0) m from eods e join users u on u.id=e.user_id where e.user_id in ({I}) and e.work_date between ? and ?"; p = [*ids, f, to]
    for k, c in (("emp", "e.user_id"), ("status", "e.status")):
        if a.get(k): sql += f" and {c}=?"; p.append(a[k])
    lo, hi = float(st("min_hours")) * 60, float(st("max_hours")) * 60; me_ = me()["id"]; out = []
    for x in q(sql + " order by e.work_date desc limit 300", p):
        fl = ("Low hours " if x["m"] < lo and x["status"] != "Draft" else "") + ("Verify excess hours" if x["m"] > hi else "")
        act = ""
        if x["status"] in ("Submitted", "Under Review") and x["user_id"] != me_:
            act = H(f'<form method="post" action="/review/{x["id"]}"><input type="hidden" name="_t" value="{session["t"]}"><input name="comment" placeholder="Comment"><button class="btn g" name="act" value="approve">Approve</button><button class="btn a" name="act" value="review">Review</button><button class="btn r" name="act" value="reject">Return</button></form>')
        out.append((x["name"], dmy(x["work_date"]), x["status"], f'{x["m"] // 60}h {x["m"] % 60}m', fl, x["review_comment"], dmy((x["reviewed_at"] or "")[:10]), act))
    miss = [r["name"] for r in q(f"select name from users where id in ({I}) and id not in (select user_id from eods where work_date=? and status in {OK})", (*ids, today()))] if today() in wdays(today(), today()) else []
    fo = H(f'<form class="bar">{inp("from", "From", "date", f)}{inp("to", "To", "date", to)}{sel("emp", "Employee", [(r, n) for r, n in people() if r in ids], a.get("emp"), blank=True)}{sel("status", "Status", [(x, x) for x in ["Draft", "Submitted", "Under Review", "Approved", "Changes Requested"]], a.get("status"), blank=True)}<button class="btn">Filter</button></form>')
    return page("Team EOD", fo, H(f'<div class="card"><b>Missing EODs today:</b> {esc(", ".join(miss)) or "None"}</div>'), tbl(["Employee", "Date", "Status", "Hours", "Flags", "Comment", "Reviewed on", "Action"], out))

@app.route("/review/<int:i>", methods=["POST"])
@need(*MG)
def review(i):
    e = one("select e.*,u.name from eods e join users u on u.id=e.user_id where e.id=?", (i,))
    if not e or e["user_id"] not in scope() or e["user_id"] == me()["id"]: abort(403)
    act = request.form["act"]; c = request.form.get("comment", "").strip()
    if e["status"] not in ("Submitted", "Under Review"): flash("Not awaiting review", "err"); return redirect("/team")
    if act == "reject" and not c: flash("A comment is required when returning an EOD", "err"); return redirect("/team")
    s = {"approve": "Approved", "reject": "Changes Requested", "review": "Under Review"}[act]
    ex("update eods set status=?,review_comment=?,reviewer_id=?,reviewed_at=? where id=?", (s, c, me()["id"], now(), i))
    ex("insert into eod_history(eod_id,action,by_user,at,note) values(?,?,?,?,?)", (i, s, me()["id"], now(), c)); log(f"EOD {i} of {e['name']} {s}")
    notify(e["user_id"], f"Your EOD for {dmy(e['work_date'])} is {s}. {c}"); flash(f"EOD marked {s}", "ok"); return redirect("/team")

