@app.route("/assignments/<int:i>/update", methods=["POST"])
@need(*MG)
def asg_upd(i):
    w, p = vis()
    a = one(f"select a.* from assignments a where a.id=? and {w}", (i, *p))
    if not a: abort(403)
    f = request.form; old = {r["user_id"] for r in q("select user_id from amembers where assignment_id=?", (i,))}; new = {int(x) for x in f.getlist("members")}
    ex("update assignments set status=? where id=?", (f["status"], i))
    if f["status"] != a["status"]: log(f"{a['code']} status {a['status']} -> {f['status']}")
    if new != old:
        ex("delete from amembers where assignment_id=?", (i,))
        for m in new: ex("insert into amembers values(?,?)", (i, m))
        for m in new - old: notify(m, f"You were assigned to {a['code']} {a['title']}")
        for m in old - new: notify(m, f"You were removed from {a['code']}")
        log(f"{a['code']} reassigned: added {sorted(new - old)}, removed {sorted(old - new)}")
    flash("Assignment updated", "ok"); return redirect("/assignments")

