def holidays():
    rs = q("select * from holidays where date between ? and ? order by date", ("2026-04-01", "2027-03-31"))
    row = lambda h: (h["name"], dmy(h["date"]), dt.date.fromisoformat(h["date"]).strftime("%A"), h["category"], h["applicability"], h["status"], "Yes" if h["active"] else "No", H(f'<form method="post" action="/holidays/{h["id"]}/toggle"><input type="hidden" name="_t" value="{session["t"]}"><button class="btn a">Toggle active / verify</button></form>') if me()["role"] == "admin" else "")
    if request.args.get("csv"): return csvout("holidays_fy_2026_27", ["Name", "Date", "Day", "Category", "Applicability", "Status", "Active"], [row(h)[:7] for h in rs])
    form = F("/holidays/add", inp("name", "Holiday name", req=True) + inp("date", "Date", "date", req=True) + sel("cat", "Category", [(x, x) for x in ["Maharashtra Public Holiday", "National", "Firm Holiday", "Restricted"]]) + inp("descr", "Description"), "Add holiday") if me()["role"] == "admin" else ""
    return page("Holidays & Leave | FY 2026-27 (01-04-2026 to 31-03-2027)", H('<p>Source: Maharashtra GAD Notification No. PHD-1125/C.R.199/Japuk (29) dated 05-12-2025 (covers calendar year 2026). Dates from 01-01-2027 to 31-03-2027 need the 2027 notification; anything marked "Needs verification" is inactive until an admin verifies it. Leave requests are not implemented in this version. <a href="/holidays?csv=1">Export CSV</a></p>'), tbl(["Holiday", "Date", "Day", "Category", "Applicability", "Status", "Active", ""], [row(h) for h in rs]), form)
@app.route("/holidays/add", methods=["POST"])
@need("admin")
def hol_add():
    f = request.form; ex("insert into holidays(name,date,category,applicability,descr,status,active) values(?,?,?,?,?,?,1)", (f["name"], f["date"], f["cat"], "Firm", f["descr"], "Admin added")); log("Holiday added " + f["name"]); return redirect("/holidays")
@app.route("/holidays/<int:i>/toggle", methods=["POST"])
@need("admin")
def hol_t(i):
    ex("update holidays set active=1-active, status=case when status='Needs verification' then 'Verified by admin' else status end where id=?", (i,)); log(f"Holiday {i} toggled"); return redirect("/holidays")

# ---------- reports ----------
@app.route("/reports")
@need(*MG)
def reports():
    s, e, r = rng(); ids = scope(); I = inl(ids); t = request.args.get("type", "emp"); A = (*ids, s, e)
    j = f"from eod_entries n join eods d on d.id=n.eod_id join users u on u.id=d.user_id join assignments a on a.id=n.assignment_id join clients c on c.id=a.client_id where d.user_id in ({I}) and d.work_date between ? and ? and d.status in {OK}"
    if t == "emp": h, rows = ["Employee", "Hours"], [tuple(x) for x in q(f"select u.name,round(sum(n.mins)/60.0,2) {j} group by u.id", A)]
    elif t == "client": h, rows = ["Client", "Hours"], [tuple(x) for x in q(f"select c.name,round(sum(n.mins)/60.0,2) {j} group by c.id", A)]
    elif t == "asg":
        w, p = vis(); h = ["ID", "Title", "Client", "Status", "Due", "Estimated hrs", "Actual hrs (approved)"]
        rows = [(x["code"], x["title"], x["cn"], x["status"], dmy(x["due"]), x["est_hours"], round(x["act"], 2)) for x in q(f"select a.*,c.name cn,(select coalesce(sum(n.mins),0)/60.0 from eod_entries n join eods d on d.id=n.eod_id where n.assignment_id=a.id and d.status='Approved') act from assignments a join clients c on c.id=a.client_id where {w}", p)]
    else:
        days = wdays(s, e); ds = set(days); h = ["Employee", "Working days", "EODs submitted", "Compliance %"]; rows = []
        for u in q(f"select id,name from users where id in ({I})", tuple(ids)):
            n = sum(1 for x in q(f"select work_date from eods where user_id=? and work_date between ? and ? and status in {OK}", (u["id"], s, e)) if x["work_date"] in ds)
            rows.append((u["name"], len(days), n, round(100 * n / len(days), 1) if days else "n/a"))
    if request.args.get("csv"): return csvout("report_" + t, h, rows)
    qs = request.query_string.decode()
    tp = H(f'<form class="bar">{sel("type", "Report", [("emp", "Employee-wise hours"), ("client", "Client-wise hours"), ("asg", "Assignment estimated vs actual"), ("comp", "EOD compliance")], t)}<select name="r">' + "".join(f'<option value="{k}" {"selected" if k == r else ""}>{v}</option>' for k, v in [("today", "Today"), ("week", "This Week"), ("month", "This Month"), ("fy", "Financial Year"), ("custom", "Custom")]) + f'</select><input type="date" name="from" value="{esc(request.args.get("from", ""))}"><input type="date" name="to" value="{esc(request.args.get("to", ""))}"><button class="btn">Run</button><a class="btn g" href="/reports?{esc(qs)}&csv=1">Download CSV</a></form>')
    return page("Reports & Analytics", tp, H(f"<p>Period {dmy(s)} to {dmy(e)}. Hours include Submitted, Under Review and Approved EODs, except where stated.</p>"), tbl(h, rows))

# ---------- settings ----------
@app.route("/settings", methods=["GET", "POST"])
@need("admin")
def settings():
    if request.method == "POST":
        for k in DEF:
            if request.form.get(k) is not None: ex("insert or replace into settings values(?,?)", (k, request.form[k].strip()))
        log("Settings updated"); flash("Settings saved", "ok"); return redirect("/settings")
    lab = {"firm_name": "Firm name", "daily_hours": "Working hours per day", "min_hours": "Low-hours threshold", "max_hours": "Excess-hours threshold", "cutoff": "EOD cut-off (HH:MM, IST)", "weekly_offs": "Weekly off weekdays (0=Mon ... 6=Sun, comma separated)"}
    form = F("/settings", "".join(inp(k, lab[k], v=st(k)) for k in DEF))
    au = [(a["at"], (one("select name from users where id=?", (a["user_id"],)) or {"name": "-"})["name"], a["action"]) for a in q("select * from audit order by id desc limit 150")]
    return page("Settings & Audit Logs", form, H("<h3>Audit log (latest 150)</h3>"), tbl(["When (IST)", "User", "Action"], au))

